 ("dns_account_required", "Account required", "Compte nécessaire"),
 ("dns_account_hint", "Create your configuration on the %1$s website, then paste its ID (6 characters) or its full hostname here.", "Créez votre configuration sur le site de %1$s, puis collez ici son identifiant (6 caractères) ou son nom d'hôte complet."),
 ("dns_account_field", "ID or hostname", "Identifiant ou nom d'hôte"),
